SELECT PetType, AVG(pet_age) AS average_age, MAX(pet_age) AS max_age
FROM Pets
GROUP BY PetType;

SELECT PetType, AVG(pet_age) AS average_age, MAX(pet_age) AS max_age
FROM Pets
GROUP BY PetType;

SELECT Year, AVG(Weight) AS AverageWeight
FROM cars_data
GROUP BY Year;

SELECT ranking_date, SUM(tours) AS total_tours
FROM rankings
GROUP BY ranking_date;

SELECT student_id, first_name, middle_name, last_name, other_student_details
FROM Students
ORDER BY last_name DESC, first_name DESC, middle_name DESC;

SELECT Pixel_aspect_ratio_PAR, Country
FROM TV_Channel
WHERE Language <> 'English';

SELECT c.Name, o.Orchestra
FROM conductor c
JOIN orchestra o ON c.Conductor_ID = o.Conductor_ID;

SELECT conductor.Name, orchestra.Orchestra
FROM conductor
JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID;

SELECT ID FROM Highschooler
EXCEPT
SELECT student_id FROM Friend;

SELECT t.cost_of_treatment, tt.treatment_type_description
FROM Treatments t
JOIN Treatment_Types tt ON t.treatment_type_code = tt.treatment_type_code;

SELECT p.professional_id, p.first_name, t.treatment_type_code
FROM Professionals p
JOIN Treatments t ON p.professional_id = t.professional_id;

SELECT DISTINCT r.property_type_description
FROM Ref_Property_Types r
JOIN Properties p ON p.property_type_code = r.property_type_code;
